const body = $input.first().json.body ?? $input.first().json;
const files = body.source_files || [];
if (!body.review_id || !Array.isArray(files) || !files.length) throw new Error('Review et fichier Excel requis.');
const expected = 'http://backend:8000/api/v1/auto-review/' + encodeURIComponent(body.review_id) + '/render?token=';
if (typeof body.render_callback_url !== 'string' || !body.render_callback_url.startsWith(expected) || !/^[a-f0-9]{64}$/.test(body.render_callback_url.slice(expected.length))) throw new Error('URL de rappel interne invalide.');
for (const f of files) {
  if (!/\.xlsx$/i.test(f.filename || '')) throw new Error('Cette version accepte uniquement les exports .xlsx.');
  if (!String(f.download_url || '').startsWith('http://minio:9000/')) throw new Error('URL source interne invalide.');
}
const ctx = {review_id: body.review_id, client_name: body.client?.name || 'Client', client_type_label: body.client_type_label || '', additional_info: String(body.additional_info || '').slice(0,2000), render_callback_url: body.render_callback_url, period: [...new Set(files.map(f=>f.period))].join(', '), ollama_url: 'http://ollama:11434', ollama_model: 'llama3.2:3b'};
return files.map(file => ({json: {...ctx, file}}));

const ctx = $('Préparer le contexte').first().json;
const rows = $input.all().map(i=>i.json).filter(r=>r && Object.keys(r).length);
if (!rows.length) throw new Error('Le fichier Excel ne contient aucune ligne exploitable.');
// Ne pas additionner des colonnes arbitraires : taux, identifiants et dates ne sont pas des totaux.
const columns = [...new Set(rows.flatMap(Object.keys))].slice(0,30);
const sample = rows.slice(0,30).map(row=>Object.fromEntries(columns.map(c=>[c, String(row[c] ?? '').slice(0,150)])));
const resume = {nombre_de_lignes: rows.length, colonnes: columns, echantillon: sample, avertissement: "Échantillon seulement : ne pas extrapoler ni présenter ces lignes comme des totaux de la période. Les fichiers sont regroupés, sans déduplication."};
return [{json:{...ctx,resume}}];

