const ctx = $('Résumer les données').first().json;
const response = $input.first().json;
if (response.done !== true || response.done_reason === 'length') throw new Error('Génération IA incomplète. Consulter cette exécution n8n.');
let plan;
try { plan = JSON.parse(response.response); } catch { throw new Error('Le modèle a renvoyé un JSON invalide.'); }
if (!plan || !Array.isArray(plan.slides) || !plan.slides.length || plan.slides.length > 8) throw new Error('Plan IA inexploitable.');
for (const s of plan.slides) {
  if (!s || !['kpis','bullets','recommendations'].includes(s.layout)) throw new Error('Mise en page IA invalide.');
}
return [{json:{review_id:ctx.review_id, render_callback_url:ctx.render_callback_url,plan}}];

return [{ json: {
